import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import { loadFont } from "@remotion/google-fonts/SchibstedGrotesk";
import React, { useEffect, useId, useLayoutEffect, useMemo } from "react";
import { AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

// Chrome parks a glyph raster on a whole pixel vertically for as long as the
// matrix that carries it is axis-aligned, so text under a slow transform
// clicks along pixel by pixel. A lean too small to see takes it off that grid.
//
// A transform that carries text is marked, and told when it moves:
//
//   const glide = useGlide();
//   transform: `scale(${s})${glide(moving)}`
//
// The mark changes nothing by itself. After every frame the blocks of text
// under a marked transform get the lean: each about its own centre, and each
// by no more than its size on the screen needs. A card, a hairline or an image
// is fine under a transform as it is, so they stay level.
//
// Text leans while its transform moves, and it keeps the lean at rest when it
// rests off the pixel grid (a scene shown smaller in a player, a camera that
// holds at 1.03): dropping the lean there would snap it to the nearest pixel,
// up to half a pixel in one frame, and picking it up would snap it back. Text
// that rests on the grid loses the lean without moving, so a scene at rest at
// full size is drawn exactly as it would be without any of this.

/**
 * Returns `glide(moving)`: append it to a transform that carries text, with
 * `moving` true on the frames where that transform changes.
 *
 * Everything else lives inside this one closure: the build of Studio
 * elements pastes this file whole into the component that uses it, where a
 * second `LEAN` or `lean` at the top level would collide.
 */
const useGlide = (() => {
  /** What `glide(false)` adds to a transform: an identity matrix, to find it by. */
  const AT_REST = " matrix(1, 0, 0, 1, 0, 0)";
  /** `glide(true)` adds it twice. */
  const MOVING = AT_REST + AT_REST;
  const MARKED = `[style*="${AT_REST.trim()}"]`;
  // Text leaves the grid once the matrix leans x into y by half of 1/1024 in
  // device pixels (Skia rounds the glyph matrix to 1/1024). A fifth over it.
  const LEAN = 0.6 / 1024;
  // Past this the text is a speck on the screen; it is left alone.
  const STEEPEST = 5;
  // How far from a whole pixel text may rest and still count as on the grid:
  // the jump it makes when the lean goes is no bigger than this.
  const ON_GRID = 0.05;

  /** The linear part of a 2D matrix: x' = a·x + c·y, y' = b·x + d·y. */
  type Lin = [a: number, b: number, c: number, d: number];
  const LEVEL: Lin = [1, 0, 0, 1];
  const times = (m: Lin, n: Lin): Lin => [
    m[0] * n[0] + m[2] * n[1],
    m[1] * n[0] + m[3] * n[1],
    m[0] * n[2] + m[2] * n[3],
    m[1] * n[2] + m[3] * n[3],
  ];
  const turned = (degrees: number): Lin => {
    const t = (degrees * Math.PI) / 180;
    return [Math.cos(t), Math.sin(t), -Math.sin(t), Math.cos(t)];
  };
  const offWhole = (n: number) => Math.abs(n - Math.round(n));

  type Block = HTMLElement | SVGTextElement | SVGSVGElement;
  let leant: Block[] = [];
  // Fonts arrive after the first pass and change what is laid out where, with
  // no render to follow: a block or a marked element that changes size is read
  // again before the frame is painted.
  let watcher: ResizeObserver | undefined;
  const watched = new WeakSet<Element>();
  const watch = (el: Element) => {
    if (watched.has(el)) return;
    watched.add(el);
    watcher ??= new ResizeObserver(() => lean());
    watcher.observe(el);
  };

  const depthOf = (el: Element) => {
    let depth = 0;
    for (let up = el.parentElement; up; up = up.parentElement) depth += 1;
    return depth;
  };

  /** The nearest box around a text node that a transform applies to. */
  const blockOf = (node: Node): Block | null => {
    for (let el = node.parentElement; el; el = el.parentElement) {
      if (el instanceof SVGElement) {
        const text = el.closest("text");
        if (!(text instanceof SVGTextElement)) return null;
        // Text that only shapes a mask or a clip is not drawn where it stands
        // and cannot turn by itself: its whole drawing leans for it.
        if (!text.closest("defs, mask, clipPath, pattern, symbol, marker"))
          return text;
        let drawing = text.ownerSVGElement;
        while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
        return drawing;
      }
      if (!(el instanceof HTMLElement)) continue;
      const { display } = getComputedStyle(el);
      if (display !== "inline" && display !== "contents") return el;
    }
    return null;
  };

  /** One pass over the page: what every element's own transforms do. */
  function reader(given: Map<Element, number>) {
    type Own = {
      /** `scale` and `transform`, without the `rotate` property. */
      lin: Lin;
      /** `rotate`, in degrees: a lean given in this pass, or the scene's own. */
      turn: number;
      /** How far down it is moved, and by what whole factor it is scaled from
       * its top left corner; null when it does anything else. */
      carry: { dy: number; k: number } | null;
    };
    const lens = new Map<Element, boolean>();
    /** Whether an element shows its children in perspective. */
    const lensOn = (el: Element | null): boolean => {
      if (!el) return false;
      const seen = lens.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const result =
        style.perspective !== "none" ||
        (style.transformStyle === "preserve-3d" && lensOn(el.parentElement));
      lens.set(el, result);
      return result;
    };
    const own = new Map<Element, Own | null>();
    const ownOf = (el: Element): Own | null => {
      const seen = own.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const m = new DOMMatrixReadOnly(
        style.transform === "none" ? "" : style.transform,
      );
      const scale = style.scale === "none" ? [] : style.scale.split(" ");
      const sx = scale.length ? Number.parseFloat(scale[0]) : 1;
      const sy = scale.length > 1 ? Number.parseFloat(scale[1]) : sx;
      const rotate = style.rotate === "none" ? [] : style.rotate.split(" ");
      let result: Own | null = null;
      // Seen in perspective, text is drawn on a layer of its own: not ours. A
      // turn out of the plane without perspective lands flat on the screen,
      // and text under it snaps like any other.
      // A push along z alone, or a half turn, leaves it flat even under a lens.
      const inPerspective =
        Math.max(Math.abs(m.m14), Math.abs(m.m24), Math.abs(m.m34)) > 1e-9 ||
        (Math.max(
          Math.abs(m.m13),
          Math.abs(m.m31),
          Math.abs(m.m23),
          Math.abs(m.m32),
        ) > 1e-6 &&
          lensOn(el.parentElement));
      if (!inPerspective && rotate.length < 2) {
        // The `scale` property acts on what `transform` has produced.
        const lin: Lin = [m.a * sx, m.b * sy, m.c * sx, m.d * sy];
        const moved =
          style.translate === "none"
            ? 0
            : (style.translate.split(" ")[1] ?? "0px");
        const k = Math.round(lin[0]);
        const whole =
          m.is2D &&
          k >= 1 &&
          Math.abs(lin[0] - k) < 1e-4 &&
          Math.abs(lin[3] - k) < 1e-4 &&
          Math.abs(lin[1]) < 1e-5 &&
          Math.abs(lin[2]) < 1e-5 &&
          rotate.length === 0 &&
          (moved === 0 || moved.endsWith("px")) &&
          // Scaled about its corner, a box stays where layout put it.
          (k === 1 || /^0(px)? 0(px)?/.test(style.transformOrigin));
        result = {
          lin,
          turn: rotate.length ? Number.parseFloat(rotate[0]) : 0,
          carry: whole
            ? { dy: sy * m.f + (moved === 0 ? 0 : Number.parseFloat(moved)), k }
            : null,
        };
      }
      own.set(el, result);
      return result;
    };
    const down = new Map<Element, Lin | null>();
    /** Everything from the page down to and including this element. */
    const linDown = (el: Element | null): Lin | null => {
      if (!el) return LEVEL;
      const seen = down.get(el);
      if (seen !== undefined) return seen;
      const above = linDown(el.parentElement);
      const mine = above && ownOf(el);
      const result =
        above && mine
          ? times(times(above, turned(given.get(el) ?? mine.turn)), mine.lin)
          : null;
      down.set(el, result);
      return result;
    };
    const carried = new Map<Element, { dy: number; k: number } | null>();
    const carryDown = (
      el: Element | null,
    ): { dy: number; k: number } | null => {
      if (!el) return { dy: 0, k: 1 };
      const seen = carried.get(el);
      if (seen !== undefined) return seen;
      const above = carryDown(el.parentElement);
      const mine = above && !given.has(el) ? ownOf(el)?.carry : null;
      const result =
        above && mine
          ? { dy: above.dy + above.k * mine.dy, k: above.k * mine.k }
          : null;
      carried.set(el, result);
      return result;
    };
    return { ownOf, linDown, carryDown };
  }

  /**
   * Whether text in an SVG rests on the grid: it is placed wherever it is told
   * to, so only when it is shown one to one and its baseline happens to land on
   * a whole pixel. `lands` is where its own space lands on the screen.
   */
  function restsOnGrid(text: SVGTextElement, lands: DOMMatrix | null) {
    if (!lands) return false;
    const dpr = window.devicePixelRatio;
    const style = getComputedStyle(text);
    const k = lands.d * dpr;
    const y = text.y.baseVal.numberOfItems
      ? text.y.baseVal.getItem(0).value
      : 0;
    return (
      text.y.baseVal.numberOfItems <= 1 &&
      text.dy.baseVal.numberOfItems === 0 &&
      !text.querySelector("tspan[y], tspan[dy], textPath") &&
      /^(auto|alphabetic)$/.test(style.dominantBaseline) &&
      /^(auto|baseline)$/.test(style.alignmentBaseline) &&
      Math.abs(lands.b) < 1e-6 &&
      Math.abs(lands.c) < 1e-6 &&
      Math.round(k) >= 1 &&
      offWhole(k) < 2e-3 &&
      offWhole((lands.d * y + lands.f) * dpr) < ON_GRID
    );
  }

  /**
   * The angle that takes a block off the grid, given what is above it (`above`)
   * and what its own transform does (`own`), both in device pixels: the lean is
   * a turn between the two. 0 when the block leans enough as it is, null when
   * no sane angle would do.
   */
  function angleFor(above: Lin, own: Lin): number | null {
    // y from x of `above · turn(θ) · own` is p·sin θ + q·cos θ.
    const p = above[3] * own[0] - above[1] * own[1];
    const q = above[1] * own[0] + above[3] * own[1];
    if (Math.abs(q) >= LEAN) return 0;
    if (Math.abs(p) < 1e-9) return null;
    // Along the turn the scene already has, so the two never cancel out.
    const sine = ((q < 0 ? -LEAN : LEAN) - q) / p;
    if (Math.abs(sine) > Math.sin((STEEPEST * Math.PI) / 180)) return null;
    return (Math.asin(sine) * 180) / Math.PI;
  }

  function lean() {
    for (const el of leant) {
      el.style.removeProperty("rotate");
      if (el instanceof SVGElement) el.style.removeProperty("translate");
    }
    leant = [];
    const zones = document.querySelectorAll<HTMLElement | SVGElement>(MARKED);
    if (zones.length === 0) return;
    // Each block of text under a mark, and whether any transform above it moves.
    const blocks = new Map<Block, boolean>();
    // The texts a whole drawing leans for.
    const standsFor = new Map<SVGSVGElement, SVGTextElement[]>();
    for (const zone of zones) {
      const moving = zone.style.transform.includes(MOVING.trim());
      const walker = document.createTreeWalker(zone, NodeFilter.SHOW_TEXT);
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (!/\S/.test(node.nodeValue ?? "")) continue;
        const block = blockOf(node);
        // A block that turns by a property of its own is left to the scene.
        if (!block || block.style.rotate) continue;
        blocks.set(block, moving || (blocks.get(block) ?? false));
        const text = node.parentElement?.closest("text");
        if (block instanceof SVGSVGElement && text instanceof SVGTextElement)
          standsFor.set(block, [...(standsFor.get(block) ?? []), text]);
      }
      watch(zone);
    }
    for (const block of blocks.keys()) watch(block);
    const dpr = window.devicePixelRatio;
    const scaled = (m: Lin): Lin => [
      m[0] * dpr,
      m[1] * dpr,
      m[2] * dpr,
      m[3] * dpr,
    ];
    // Outer blocks first: a block inside a leaning one takes only what it
    // still lacks, so leans never pile up. Everything is read before anything
    // is written; `given` stands in for the leans not yet on the page.
    const given = new Map<Element, number>();
    const { ownOf, linDown, carryDown } = reader(given);
    const writes: (() => void)[] = [];
    const ordered = [...blocks.keys()].sort((a, b) => depthOf(a) - depthOf(b));
    for (const el of ordered) {
      const moving = blocks.get(el) === true;
      if (el instanceof HTMLElement) {
        const above = linDown(el.parentElement);
        const mine = ownOf(el);
        if (!above || !mine) continue;
        if (!moving) {
          // Layout puts a baseline on a whole pixel wherever the box itself
          // sits, so text is on the grid when the transforms around it only
          // move it by whole pixels and show it one to one (or two, or three).
          const carry = carryDown(el);
          if (
            carry &&
            offWhole(carry.k * dpr) < 2e-3 &&
            offWhole(carry.dy * dpr) < ON_GRID
          )
            continue;
        }
        const angle = angleFor(scaled(above), mine.lin);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      if (el instanceof SVGSVGElement) {
        // A whole drawing: what it does itself is its own transform and the
        // scale of its viewBox, read off where it lands on the screen.
        const above = linDown(el.parentElement);
        const lands = el.getScreenCTM();
        const det = above ? above[0] * above[3] - above[1] * above[2] : 0;
        if (!above || !lands || Math.abs(det) < 1e-12) continue;
        if (
          !moving &&
          (standsFor.get(el) ?? []).every((text) =>
            restsOnGrid(text, text.getScreenCTM()),
          )
        )
          continue;
        const mine = times(
          [above[3] / det, -above[1] / det, -above[2] / det, above[0] / det],
          [lands.a, lands.b, lands.c, lands.d],
        );
        const angle = angleFor(scaled(above), mine);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      // Its drawing leans as a whole already.
      let drawing = el.ownerSVGElement;
      while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
      if (drawing && given.has(drawing)) continue;
      // Text in an SVG is placed wherever it is told to, so it is on the grid
      // only when its baseline happens to land on a whole pixel.
      const frame = el.parentNode;
      if (!(frame instanceof SVGGraphicsElement) || el.style.translate)
        continue;
      const outer = frame.getScreenCTM();
      const whole = el.getScreenCTM();
      if (
        !outer ||
        !whole ||
        Math.abs(outer.a * outer.d - outer.b * outer.c) < 1e-12
      )
        continue;
      // What the text element itself does, in the space it is placed in.
      const mine = outer.inverse().multiply(whole);
      if (!moving && restsOnGrid(el, whole)) continue;
      const angle = angleFor(scaled([outer.a, outer.b, outer.c, outer.d]), [
        mine.a,
        mine.b,
        mine.c,
        mine.d,
      ]);
      if (!angle) continue;
      // An SVG element turns about the corner of its drawing. A move brings
      // the turn to the middle of the text instead.
      const box = el.getBBox();
      const [cx, cy] = [box.x + box.width / 2, box.y + box.height / 2];
      const [px, py] = [
        mine.a * cx + mine.c * cy + mine.e,
        mine.b * cx + mine.d * cy + mine.f,
      ];
      const [cos, sin] = [turned(angle)[0], turned(angle)[1]];
      const [tx, ty] = [px - (px * cos - py * sin), py - (px * sin + py * cos)];
      writes.push(() => {
        el.style.setProperty("rotate", `${angle}deg`);
        el.style.setProperty("translate", `${tx}px ${ty}px`);
      });
      leant.push(el);
    }
    for (const write of writes) write();
  }

  const useFrameEffect =
    typeof window === "undefined" ? useEffect : useLayoutEffect;

  function useGlide() {
    // No dependencies: the lean follows whatever this frame laid out.
    useFrameEffect(lean);
    return glide;
  }

  const glide = (moving: boolean) => (moving ? MOVING : AT_REST);

  return useGlide;
})();

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const { fontFamily: mono } = loadMono("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const manrope = loadManrope("normal", {
  weights: ["600"],
  subsets: ["latin"],
});

const REMOCN_R_PATH =
  "M 0.01 0.81 C 0.01 1.73, 0.36 2.79, 1.09 4.13 C 4.91 11.04, 13.45 17.16, 21.7 18.9 C 22.94 19.16, 23.18 19.16, 51.39 19.27 C 76.07 19.36, 80.02 19.4, 81.32 19.57 C 89.89 20.69, 96.2 24.68, 99.38 31.01 C 103.19 38.56, 102.53 50.1, 97.91 57.07 C 94.66 61.96, 89.68 64.99, 83.26 66 C 82.81 66.07, 70.18 66.83, 55.2 67.69 C 24.82 69.43, 27.03 69.23, 24.18 70.4 C 19.9 72.15, 14.84 75.7, 10.65 79.89 C 4.86 85.68, 1.3 91.91, 0.25 98.13 C 0.12 98.85, 0.08 103.13, 0.04 116.66 L 0 134.26 9.5 134.26 L 19 134.26 19.05 119.41 C 19.1 103.27, 19.08 103.82, 19.82 101.04 C 21.79 93.65, 27.86 88.75, 36.45 87.63 C 37.23 87.53, 39.41 87.5, 43.57 87.53 C 50.12 87.59, 50.75 87.65, 53.22 88.45 C 56.61 89.56, 59.67 91.86, 62.02 95.07 C 62.52 95.76, 69.35 103.85, 77.2 113.07 C 85.04 122.28, 91.63 130.04, 91.85 130.32 C 92.07 130.59, 92.5 131.34, 92.82 131.97 C 93.52 133.35, 94.11 133.93, 95.06 134.13 C 95.5 134.23, 98.97 134.26, 106.36 134.23 L 117.01 134.19 100.82 113.07 C 91.91 101.45, 84.52 91.78, 84.39 91.57 C 83.36 89.89, 83.66 87.53, 85.09 86 C 85.79 85.25, 86.36 84.94, 88.07 84.38 C 96.18 81.72, 104.15 76.62, 109.97 70.36 C 120.59 58.93, 124.06 44.32, 119.44 30.43 C 114.59 15.81, 101.93 4.02, 87.64 0.83 C 83.93 0.01, 88.09 0.08, 41.85 0.04 L 0.01 0 0.01 0.81 Z";

/** Full logo as on remocn.dev: R mark (0.76em tall, baseline-aligned) + "emocn" in Manrope 600. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

export interface IpoOpenProps {
  /** Ticker symbol, set huge. Fictional, 1–5 capital letters reads best. */
  symbol?: string;
  /** Small mono line above the symbol. */
  label?: string;
  /** The IPO price the opening print starts from. */
  ipoPrice?: number;
  /** The first trade the price races to. */
  openPrice?: number;
  /** Clock in the corner; ticks over to this on the bell. */
  openTime?: string;
  /** Brand in the corner bug; "remocn" renders the real logo. */
  name?: string;
  /** Replaces the logo / name in the corner bug. */
  logo?: React.ReactNode;
  /** Tag in the chip before the bell. */
  priceTag?: string;
  /** Frames the opening print takes to race to `openPrice`. */
  countLength?: number;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  /** Background fill under the sunrise; "transparent" drops it. */
  background?: string;
  /** Typeface for the symbol and price. Load it yourself; Schibsted Grotesk by default. */
  fontFamily?: string;
  /** Size of the foreground, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

// Schibsted Grotesk 500 advances per em for A–Z (harfbuzz, wght 500),
// tabular figures .635, "$" .574, "." .287, cap height .703.
const SCHIBSTED: Record<string, number> = {
  A: 0.71,
  B: 0.654,
  C: 0.708,
  D: 0.708,
  E: 0.591,
  F: 0.567,
  G: 0.721,
  H: 0.729,
  I: 0.373,
  J: 0.55,
  K: 0.678,
  L: 0.555,
  M: 0.886,
  N: 0.739,
  O: 0.769,
  P: 0.63,
  Q: 0.769,
  R: 0.648,
  S: 0.623,
  T: 0.656,
  U: 0.685,
  V: 0.688,
  W: 0.955,
  X: 0.675,
  Y: 0.633,
  Z: 0.606,
};
const DIGIT = 0.635;
const DOLLAR = 0.574;
const DOT = 0.287;
const CAP = 0.703;
const SYM_TRACK = -0.035;
const PRICE_TRACK = -0.02;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_RACE = Easing.bezier(0.3, 0, 0.12, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// Beat sheet (30fps, speed 1):
//   0–26   LISTED TODAY, then the symbol rises letter by letter out of a
//          baseline window; the IPO price and its tag settle underneath
//  34–35   the bell: a two-frame inverted flash, the clock flips to the open,
//          a shockwave line tears out sideways from the centre
//  37–87   the opening print races up on rolling tabular reels, the live move
//          counting in the chip, the sunrise ground climbing with it
//  87–99   the price lands, the chip pops into the gradient
//  99–     poster holds
const BELL = 34;
const RACE_AT = 37;
const RACE_LEN = 50;

// gradients.sh "rise" (bg #030306): #fff1e2 #ff8a3d #a3301a #2a0d0a.
const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F5F4F1",
    muted: "#85838A",
    hair: "rgba(245,244,241,0.16)",
    chipInk: "#1E0B07",
    chip: "linear-gradient(105deg, #FFF1E2 0%, #FFC59A 34%, #FF8A3D 72%, #E0703B 100%)",
    ground: (k: number) =>
      [
        `radial-gradient(${70 + 30 * k}% ${16 + 34 * k}% at 50% 104%, rgba(255,241,226,${0.95 * k}) 0%, rgba(255,138,61,${0.9 * k}) 22%, rgba(163,48,26,${0.75 * k}) 52%, rgba(42,13,10,${0.6 * k}) 76%, rgba(42,13,10,0) 100%)`,
        `radial-gradient(120% ${30 + 30 * k}% at 50% 100%, rgba(163,48,26,${0.28 * k}) 0%, rgba(42,13,10,0) 70%)`,
      ].join(", "),
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#8A8883",
    hair: "rgba(18,18,20,0.14)",
    chipInk: "#FFF1E2",
    chip: "linear-gradient(105deg, #2A0D0A 0%, #A3301A 46%, #E0703B 78%, #FF8A3D 100%)",
    ground: (k: number) =>
      [
        `radial-gradient(${70 + 30 * k}% ${16 + 34 * k}% at 50% 104%, rgba(255,138,61,${0.85 * k}) 0%, rgba(255,138,61,${0.42 * k}) 34%, rgba(255,241,226,${0.5 * k}) 70%, rgba(255,241,226,0) 100%)`,
      ].join(", "),
  },
} as const;

const fmt = (cents: number) => {
  const c = Math.round(cents);
  return `${Math.floor(c / 100)}.${String(c % 100).padStart(2, "0")}`;
};

/** Odometer position for the column with place value `p` (in cents). */
function columnPos(cents: number, p: number) {
  if (p === 1) return cents;
  const below = ((cents % p) + p) % p;
  const carry = Math.max(0, (below - 0.9 * p) / (0.1 * p));
  return Math.floor(cents / p) + carry;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function IpoOpen({
  symbol = "RMCN",
  label = "Listed today",
  ipoPrice = 18,
  openPrice = 42.6,
  openTime = "09:30",
  name = "remocn",
  logo,
  priceTag = "IPO price",
  countLength = RACE_LEN,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = sans,
  scale = 1,
  delay = 0,
  speed = 1,
  theme = "dark",
}: IpoOpenProps) {
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H } = useSceneConfig();
  const u = H / 720;
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const LAND = RACE_AT + countLength;
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  // ---- symbol layout -------------------------------------------------------
  const letters = Array.from(symbol.toUpperCase());
  const symEm =
    letters.reduce((w, ch) => w + (SCHIBSTED[ch] ?? 0.68) + SYM_TRACK, 0) -
    SYM_TRACK;
  const S = Math.min(H * 0.43, (W * 0.74) / symEm);
  const symBase = H * 0.505;
  const symX0 = (W - symEm * S) / 2;

  // ---- price layout ($dd.cc, digits on reels) -------------------------------
  const startC = Math.round(ipoPrice * 100);
  const endC = Math.round(openPrice * 100);
  const intDigits = Math.max(1, String(Math.floor(endC / 100)).length);
  const places: number[] = [];
  for (let i = intDigits - 1; i >= 0; i--) places.push(10 ** (i + 2));
  places.push(10, 1);
  const P = H * 0.19;
  const priceBase = H * 0.815;
  const glyphs: Array<{ kind: "$" | "." | number; x: number; w: number }> = [];
  {
    let x = 0;
    glyphs.push({ kind: "$", x, w: DOLLAR });
    x += DOLLAR + PRICE_TRACK;
    places.forEach((pl, i) => {
      if (i === intDigits) {
        glyphs.push({ kind: ".", x, w: DOT });
        x += DOT + PRICE_TRACK;
      }
      glyphs.push({ kind: pl, x, w: DIGIT });
      x += DIGIT + PRICE_TRACK;
    });
  }
  const last = glyphs[glyphs.length - 1];
  const priceW = (last.x + last.w) * P;
  const chipH = 0.64 * P;
  const chipFont = 0.33 * P;
  const chipW = chipFont * 5.5;
  const gap = 0.22 * P;
  const rowX0 = (W - (priceW + gap + chipW)) / 2;
  const chipX = rowX0 + priceW + gap;
  const chipY = priceBase - (CAP * P) / 2 - chipH / 2;
  const ruleY = H * 0.588;

  // ---- timing ----------------------------------------------------------------
  const race = EASE_RACE(Math.max(0, Math.min(1, (t - RACE_AT) / countLength)));
  const raceAt = (tt: number) =>
    startC +
    (endC - startC) *
      EASE_RACE(Math.max(0, Math.min(1, (tt - RACE_AT) / countLength)));
  const cents = raceAt(t);
  const pct = (cents / startC - 1) * 100;
  const flash = t >= BELL && t < BELL + 2;
  const opened = t >= BELL;
  const landed = t >= LAND;
  const riseAt = (tt: number, a: number, len = 18) =>
    interpolate(tt, [a, a + len], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const rise = (a: number, len = 18) => riseAt(t, a, len);
  const kickAt = (tt: number) =>
    interpolate(tt, [BELL, BELL + 14], [1.045, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  const kick = kickAt(t);
  // Whether a value is still travelling: compared with the neighbouring frames.
  const stirs = (at: (tt: number) => number, eps = 1e-3) =>
    Math.abs(at(t + 1) - at(t)) > eps || Math.abs(at(t) - at(t - 1)) > eps;
  const shock = interpolate(t, [BELL, BELL + 16], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.05, 0.7, 0.1, 1),
  });
  const shock2 = interpolate(t, [BELL + 3, BELL + 22], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.05, 0.7, 0.1, 1),
  });
  const popAt = (tt: number) =>
    interpolate(tt, [LAND - 2, LAND + 5, LAND + 14], [0, 1.09, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  const pop = popAt(t);
  const fill = interpolate(t, [LAND - 2, LAND + 4], [0, 1], CLAMP);
  const groundK =
    0.12 * rise(BELL, 10) +
    0.7 * race +
    0.18 * interpolate(t, [LAND - 4, LAND + 16], [0, 1], CLAMP);

  // corner clock: one second before the bell, ticking after it
  const secs = Math.floor((t - BELL) / 30);
  const [hh, mm] = openTime.split(":").map((n) => Number(n));
  const clockMin = hh * 60 + mm + Math.floor(secs / 60);
  const clock = `${String(Math.floor(clockMin / 60) % 24).padStart(2, "0")}:${String(((clockMin % 60) + 60) % 60).padStart(2, "0")}:${String(((secs % 60) + 60) % 60).padStart(2, "0")}`;

  // The letters rise by their `y` and kick by a scale; the price glyphs
  // rise and roll. SVG text can't carry the mark, so the drawing leans while
  // either group moves, and already while the letters wait below their window:
  // a lean that came on as the first one starts would snap them all.
  const symbolMoving =
    t < 4 ||
    stirs((tt) => kickAt(tt) * S) ||
    letters.some((_, i) =>
      stirs((tt) => riseAt(tt, 4 + i * 3, 16) * CAP * S * 1.05),
    );
  const priceMoving =
    stirs((tt) => raceAt(tt) / 100) ||
    glyphs.some((_, i) => stirs((tt) => riseAt(tt, 14 + i * 2, 16) * 0.3 * P));

  // ---- reels ------------------------------------------------------------------
  const step = (CAP + 0.3) * P;
  const digitOf = (n: number) => ((Math.floor(n) % 10) + 10) % 10;
  const reels = glyphs.map((g, i) => {
    const gx = rowX0 + (g.x + g.w / 2) * P;
    const enter = rise(14 + i * 2, 16);
    if (g.kind === "$" || g.kind === ".") {
      return (
        <text
          key={`m${g.kind}`}
          x={gx}
          y={priceBase + (1 - enter) * 0.3 * P}
          opacity={enter}
        >
          {g.kind}
        </text>
      );
    }
    const pl = g.kind;
    const pos = columnPos(cents, pl);
    const v = Math.abs(
      columnPos(raceAt(t + 0.5), pl) - columnPos(raceAt(t - 0.5), pl),
    );
    const base = Math.floor(pos);
    const f = pos - base;
    const sd = Math.min(0.09, v * 0.06) * P;
    // a leading zero stays hidden until the race carries into it
    const lead = pl >= 1000 && cents < pl;
    return (
      <g
        key={`d${pl}`}
        opacity={enter * (lead ? 0 : 1)}
        transform={`translate(0 ${(1 - enter) * 0.3 * P - f * step})`}
      >
        <g filter={sd > 0.2 ? `url(#${uid}b${pl})` : undefined}>
          <text x={gx} y={priceBase}>
            {digitOf(base)}
          </text>
          {f > 0.001 ? (
            <text x={gx} y={priceBase + step}>
              {digitOf(base + 1)}
            </text>
          ) : null}
        </g>
        <filter
          id={`${uid}b${pl}`}
          filterUnits="userSpaceOnUse"
          x={0}
          y={0}
          width={W}
          height={H}
        >
          <feGaussianBlur stdDeviation={`0 ${sd.toFixed(2)}`} />
        </filter>
      </g>
    );
  });

  const shockW = shock * W * 0.62;
  const shockT = (1 - shock) ** 1.5 * 14 * u + 1.5 * u;
  const ruleSettle = interpolate(t, [BELL + 10, BELL + 26], [0, 1], CLAMP);

  return (
    <AbsoluteFill
      style={{
        background:
          background === "transparent" ? undefined : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      {/* sunrise ground, climbing with the opening print */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: p.ground(groundK),
        }}
      />

      <ScaleLayer scale={scale}>
        <svg
          width={W}
          height={H}
          viewBox={`0 0 ${W} ${H}`}
          style={{
            position: "absolute",
            inset: 0,
            transform: glide(symbolMoving || priceMoving),
          }}
          role="img"
          aria-label={`${symbol} opens at ${fmt(endC)}, IPO price ${fmt(startC)}`}
        >
          <defs>
            <linearGradient id={`${uid}feather`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0" stopColor="#fff" stopOpacity={0} />
              <stop offset="0.16" stopColor="#fff" />
              <stop offset="0.84" stopColor="#fff" />
              <stop offset="1" stopColor="#fff" stopOpacity={0} />
            </linearGradient>
            <mask
              id={`${uid}win`}
              maskUnits="userSpaceOnUse"
              x={0}
              y={0}
              width={W}
              height={H}
            >
              <rect
                x={0}
                y={priceBase - CAP * P - 0.16 * P}
                width={W}
                height={CAP * P + 0.32 * P}
                fill={`url(#${uid}feather)`}
              />
            </mask>
            <clipPath id={`${uid}symWin`}>
              <rect x={0} y={0} width={W} height={symBase + 0.02 * S} />
            </clipPath>
            <linearGradient id={`${uid}shock`} x1="0" y1="0" x2="1" y2="0">
              <stop offset="0" stopColor={fg} stopOpacity={0} />
              <stop offset="0.35" stopColor={fg} stopOpacity={0.5} />
              <stop offset="0.5" stopColor={fg} />
              <stop offset="0.65" stopColor={fg} stopOpacity={0.5} />
              <stop offset="1" stopColor={fg} stopOpacity={0} />
            </linearGradient>
          </defs>

          {/* the symbol rises out of its baseline, kicks on the bell */}
          <g
            clipPath={`url(#${uid}symWin)`}
            transform={`translate(${W / 2} ${symBase}) scale(${kick}) translate(${-W / 2} ${-symBase})`}
          >
            <g
              fontFamily={fontFamily}
              fontWeight={500}
              fontSize={S}
              fill={fg}
              textAnchor="start"
            >
              {letters.map((ch, i) => {
                const x =
                  symX0 +
                  letters
                    .slice(0, i)
                    .reduce(
                      (w, c) => w + (SCHIBSTED[c] ?? 0.68) + SYM_TRACK,
                      0,
                    ) *
                    S;
                const k = rise(4 + i * 3, 16);
                return (
                  <text
                    key={`${ch}${x}`}
                    x={x}
                    y={symBase + (1 - k) * CAP * S * 1.05}
                  >
                    {ch}
                  </text>
                );
              })}
            </g>
          </g>

          {/* shockwave out of the centre, settling into a hairline rule */}
          {opened ? (
            <>
              <rect
                x={W / 2 - shockW}
                y={ruleY - shockT / 2}
                width={shockW * 2}
                height={shockT}
                fill={`url(#${uid}shock)`}
                opacity={1 - ruleSettle * 0.8}
              />
              <rect
                x={W / 2 - shock2 * W * 0.75}
                y={ruleY - 0.75 * u}
                width={shock2 * W * 1.5}
                height={1.5 * u}
                fill={`url(#${uid}shock)`}
                opacity={(1 - shock2) * 0.7}
              />
            </>
          ) : null}
          <rect
            x={W * 0.08}
            y={ruleY - 0.5 * u}
            width={W * 0.84}
            height={1 * u}
            fill={p.hair}
            opacity={ruleSettle}
          />

          {/* the price on reels */}
          <g
            fontFamily={fontFamily}
            fontWeight={500}
            fontSize={P}
            fill={fg}
            textAnchor="middle"
            letterSpacing="0"
            style={{ fontVariantNumeric: "tabular-nums" }}
          >
            <g mask={`url(#${uid}win)`}>
              {reels.filter((_, i) => typeof glyphs[i].kind === "number")}
            </g>
            {reels.filter((_, i) => typeof glyphs[i].kind !== "number")}
          </g>
        </svg>

        {/* chip: IPO tag before the bell, live move during the race, gradient on the land */}
        <div
          style={{
            position: "absolute",
            left: chipX,
            top: chipY,
            width: chipW,
            height: chipH,
            borderRadius: chipH / 2,
            boxShadow: `inset 0 0 0 ${1.5 * u}px ${p.hair}`,
            opacity: rise(18, 16),
            transform: `translateY(${(1 - rise(18, 16)) * 0.2 * P}px) scale(${landed || t >= LAND - 2 ? pop : 1})${glide(
              stirs((tt) => riseAt(tt, 18, 16) * 0.2 * P) ||
                (t >= LAND - 3 && stirs((tt) => popAt(tt) * chipW)),
            )}`,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              background: p.chip,
              opacity: fill,
            }}
          />
          <div
            style={{
              position: "absolute",
              inset: 0,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: 0.32 * chipFont,
              color: fill > 0.5 ? p.chipInk : fg,
              lineHeight: 1,
            }}
          >
            {opened ? (
              <>
                <svg
                  width={0.62 * chipFont}
                  height={0.54 * chipFont}
                  viewBox="0 0 10 8.66"
                  aria-hidden
                  style={{ display: "block" }}
                >
                  <path
                    d="M5 0 L10 8.66 L0 8.66 Z"
                    fill={fill > 0.5 ? p.chipInk : accent}
                  />
                </svg>
                <span
                  style={{
                    fontFamily,
                    fontWeight: 500,
                    fontSize: chipFont,
                    letterSpacing: "-0.01em",
                  }}
                >
                  {/* tabular digits so the live move doesn't wobble, a
                    proportional point so it doesn't gape */}
                  {Array.from(`+${pct.toFixed(1)}%`).map((ch, i) => (
                    <span
                      key={i}
                      style={{
                        fontVariantNumeric:
                          ch === "." ? "normal" : "tabular-nums",
                      }}
                    >
                      {ch}
                    </span>
                  ))}
                </span>
              </>
            ) : (
              <span
                style={{
                  fontFamily: mono,
                  fontWeight: 400,
                  fontSize: chipFont * 0.6,
                  letterSpacing: "0.12em",
                  textTransform: "uppercase",
                  color: p.muted,
                }}
              >
                {priceTag}
              </span>
            )}
          </div>
        </div>

        {/* label above the symbol */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: H * 0.115,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            gap: 12 * u,
            fontFamily: mono,
            fontWeight: 500,
            fontSize: 18 * u,
            letterSpacing: "0.16em",
            textTransform: "uppercase",
            color: fg,
            opacity: rise(0, 14),
            transform: `translateY(${(1 - rise(0, 14)) * 8 * u}px)${glide(stirs((tt) => riseAt(tt, 0, 14) * 8 * u))}`,
            lineHeight: 1,
          }}
        >
          <div
            style={{
              width: 9 * u,
              height: 9 * u,
              borderRadius: 99,
              background: accent,
            }}
          />
          {label}
        </div>

        {/* corner bug: logo left, market clock right */}
        <div
          style={{
            position: "absolute",
            left: W * 0.045,
            top: H * 0.06,
            opacity: rise(-6, 14),
          }}
        >
          {logo ??
            (name.trim().toLowerCase() === "remocn" ? (
              <RemocnLogo fontSize={24 * u} color={fg} />
            ) : (
              <span
                style={{
                  fontFamily,
                  fontWeight: 500,
                  fontSize: 24 * u,
                  letterSpacing: "-0.02em",
                  color: fg,
                }}
              >
                {name}
              </span>
            ))}
        </div>
        <div
          style={{
            position: "absolute",
            right: W * 0.045,
            top: H * 0.06 + 3 * u,
            fontFamily: mono,
            fontWeight: 400,
            fontSize: 17 * u,
            letterSpacing: "0.06em",
            color: opened ? fg : p.muted,
            fontVariantNumeric: "tabular-nums",
            opacity: rise(-6, 14),
            lineHeight: 1,
          }}
        >
          {clock}
        </div>
      </ScaleLayer>

      {/* the bell: two inverted frames */}
      {flash ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: "#FFFFFF",
            mixBlendMode: "difference",
            opacity: 1,
          }}
        />
      ) : null}
    </AbsoluteFill>
  );
}
